```julia
@testset "localcontrast 补充" begin
    @testset "A 补充类型" begin
        gray_u16 = reshape(UInt16.(mod.(0:63, 256)), 8, 8)
        B_u16 = localcontrast(gray_u16)
        @test size(B_u16) == size(gray_u16)
        @test eltype(B_u16) == UInt16

        gray_i8 = reshape(Int8.(mod.(0:63, 256) .- 128), 8, 8)
        B_i8 = localcontrast(gray_i8)
        @test size(B_i8) == size(gray_i8)
        @test eltype(B_i8) == Int8

        gray_i16 = reshape(Int16.(mod.(0:63, 256) .- 32768), 8, 8)
        B_i16 = localcontrast(gray_i16)
        @test size(B_i16) == size(gray_i16)
        @test eltype(B_i16) == Int16
    end

    @testset "edgeThreshold 补充类型" begin
        G = reshape(Float32.(range(0, 1; length=64)), 8, 8)
        edge_types = (Float32, Int8, Int16, Int32, UInt8, UInt16, UInt32, UInt64)
        for T in edge_types
            threshold = T === Float32 ? Float32(0.4) : one(T)
            B = localcontrast(G, threshold, 0.5)
            @test size(B) == size(G)
            @test eltype(B) == Float32
            @test all(isfinite, B)
        end
    end

    @testset "amount 补充类型" begin
        G = reshape(Float32.(range(0, 1; length=64)), 8, 8)
        amount_types = (Float32, Int8, Int16, Int32, UInt8, UInt16, UInt32, UInt64)
        for T in amount_types
            amount = T === Float32 ? Float32(0.5) : one(T)
            B = localcontrast(G, 0.4, amount)
            @test size(B) == size(G)
            @test eltype(B) == Float32
            @test all(isfinite, B)
        end
    end

    @testset "显式默认值与有效边界" begin
        G = reshape(Float32.(range(0, 1; length=64)), 8, 8)

        B_default = localcontrast(G, 0.3, 0.25)
        @test size(B_default) == size(G)
        @test eltype(B_default) == Float32
        @test all(isfinite, B_default)

        B_edge1 = localcontrast(G, 1.0, 0.5)
        @test size(B_edge1) == size(G)
        @test eltype(B_edge1) == Float32
        @test all(isfinite, B_edge1)

        B_amt_pos1 = localcontrast(G, 0.4, 1.0)
        @test size(B_amt_pos1) == size(G)
        @test eltype(B_amt_pos1) == Float32
        @test all(isfinite, B_amt_pos1)

        B_amt_neg1 = localcontrast(G, 0.4, -1.0)
        @test size(B_amt_neg1) == size(G)
        @test eltype(B_amt_neg1) == Float32
        @test all(isfinite, B_amt_neg1)
    end
end
