```julia
@testset "localcontrast 补充 baseline" begin
    # MATLAB baseline 数值来自用户运行 baseline_localcontrast.m（见对话记录）。

    @testset "A 补充类型" begin
        gray_u16 = reshape(UInt16.(mod.(0:63, 256)), 8, 8)
        B_u16 = localcontrast(gray_u16)
        @test size(B_u16) == size(gray_u16)
        @test eltype(B_u16) == UInt16
        # MATLAB: sum=2016, sumsq=85344
        @test sum(Int, B_u16) == 2016
        @test sum(x -> Int(x)^2, B_u16) == 85344

        gray_i8 = reshape(Int8.(mod.(0:63, 256) .- 128), 8, 8)
        B_i8 = localcontrast(gray_i8)
        @test size(B_i8) == size(gray_i8)
        @test eltype(B_i8) == Int8
        # MATLAB: sum=-5883, sumsq=577503
        @test sum(Int, B_i8) == -5883
        @test sum(x -> Int(x)^2, B_i8) == 577503

        gray_i16 = reshape(Int16.(mod.(0:63, 256) .- 32768), 8, 8)
        B_i16 = localcontrast(gray_i16)
        @test size(B_i16) == size(gray_i16)
        @test eltype(B_i16) == Int16
        # MATLAB: sum=-2095136, sumsq=68587441504
        @test sum(Int, B_i16) == -2095136
        @test sum(x -> Int(x)^2, B_i16) == 68587441504
    end

    G = reshape(Float32.(range(0, 1; length=64)), 8, 8)

    @testset "edgeThreshold 补充类型" begin
        edge_types = (Float32, Int8, Int16, Int32, UInt8, UInt16, UInt32, UInt64)
        for T in edge_types
            threshold = T === Float32 ? Float32(0.4) : one(T)
            B = localcontrast(G, threshold, 0.5)
            @test size(B) == size(G)
            @test eltype(B) == Float32

            expected_sum = T === Float32 ? 33.182732440531254 : 40.186603620648384
            expected_sumsq = T === Float32 ? 24.288496763646009 : 40.383467827696037
            @test sum(Float64, B) ≈ expected_sum atol=1e-3
            @test sum(x -> Float64(x)^2, B) ≈ expected_sumsq atol=1e-3
        end
    end

    @testset "amount 补充类型" begin
        amount_types = (Float32, Int8, Int16, Int32, UInt8, UInt16, UInt32, UInt64)
        for T in amount_types
            amount = T === Float32 ? Float32(0.5) : one(T)
            B = localcontrast(G, 0.4, amount)
            @test size(B) == size(G)
            @test eltype(B) == Float32

            expected_sum = T === Float32 ? 33.182732440531254 : 35.219901986420155
            expected_sumsq = T === Float32 ? 24.288496763646009 : 30.705158390091064
            @test sum(Float64, B) ≈ expected_sum atol=1e-3
            @test sum(x -> Float64(x)^2, B) ≈ expected_sumsq atol=1e-3
        end
    end

    @testset "显式默认值与有效边界" begin
        cases = [
            (0.3, 0.25, 32.227222420275211, 22.119504330640677),
            (1.0, 0.5, 40.186603620648384, 40.383467827696037),
            (0.4, 1.0, 35.219901986420155, 30.705158390091064),
            (0.4, -1.0, 26.978663444519043, 13.373726638127067),
        ]
        for (edge, amount, expected_sum, expected_sumsq) in cases
            B = localcontrast(G, edge, amount)
            @test size(B) == size(G)
            @test eltype(B) == Float32
            @test sum(Float64, B) ≈ expected_sum atol=1e-3
            @test sum(x -> Float64(x)^2, B) ≈ expected_sumsq atol=1e-3
        end
    end
end
